package eval

func questRewardsSuite() Suite {
	base := questDependenciesSuite()
	return Suite{ID: "065-quest-rewards", Name: "Campaign Play 065: Quest Rewards", Tests: append(base.Tests,
		playTestExactJSON("play-quest-reward-create", "DM creates a quest for reward testing", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-reward", "title": "Recover the cache", "depends_on": []any{}}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"quest_id": "quest-reward", "title": "Recover the cache", "depends_on": []any{}, "state": "locked"}),
		playTest("play-quest-reward-player-configure-forbidden", "Players cannot configure quest rewards", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-quest-reward-configure-unknown", "Unknown quest reward configuration returns 404", "PUT", "/v1/play/campaigns/play-2/quests/quest-missing/rewards", map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-quest-reward-configure-negative-xp", "Quest reward XP must be nonnegative", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": -1, "items": map[string]any{"healing-potion": 1}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-reward-configure-unknown-item", "Quest reward items must be valid catalog IDs", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": 100, "items": map[string]any{"longsword": 1}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-reward-configure-zero-item", "Quest reward item quantities must be positive", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 0}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-quest-reward-configure", "DM configures deterministic quest rewards", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-reward", "title": "Recover the cache", "depends_on": []any{}, "state": "locked", "rewards": map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}}),
		playTest("play-quest-reward-award-early", "Quest rewards cannot be awarded before completion", "POST", "/v1/play/campaigns/play-2/quests/quest-reward/rewards/award", nil, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-quest-reward-active", "DM activates reward quest", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-reward", "title": "Recover the cache", "depends_on": []any{}, "state": "active", "rewards": map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}}),
		playTestExactJSON("play-quest-reward-completed", "DM completes reward quest", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/state", map[string]any{"state": "completed"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-reward", "title": "Recover the cache", "depends_on": []any{}, "state": "completed", "rewards": map[string]any{"xp": 100, "items": map[string]any{"healing-potion": 1}}}),
		playTest("play-quest-reward-configure-completed-conflict", "Completed quests cannot have rewards reconfigured", "PUT", "/v1/play/campaigns/play-2/quests/quest-reward/rewards", map[string]any{"xp": 50, "items": map[string]any{"torch": 1}}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-quest-reward-award-player-forbidden", "Players cannot award quest rewards", "POST", "/v1/play/campaigns/play-2/quests/quest-reward/rewards/award", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTestExactJSON("play-quest-reward-award", "DM awards configured rewards once to every campaign member", "POST", "/v1/play/campaigns/play-2/quests/quest-reward/rewards/award", nil, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"quest_id": "quest-reward", "awarded": true, "xp": 100, "items": map[string]any{"healing-potion": 1}}),
		playTest("play-quest-reward-award-duplicate", "Duplicate quest reward award conflicts", "POST", "/v1/play/campaigns/play-2/quests/quest-reward/rewards/award", nil, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-character-rewards-unknown", "Unknown character reward read returns 404", "GET", "/v1/play/campaigns/play-2/characters/play-char-missing/rewards", nil, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTestExactJSON("play-character-rewards-player-a", "Player A reads deterministic quest rewards for their character", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/rewards", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "xp": 100, "items": map[string]any{"healing-potion": 1}}),
		playTestExactJSON("play-character-rewards-player-b", "Player B also received the same quest rewards exactly once", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/rewards", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-b", "xp": 100, "items": map[string]any{"healing-potion": 1}}),
	)}
}
